/*
 * A297180  a(n) is the smallest positive integer of length (distance from
 *          origin) n in the Cayley graph of the integers generated by all
 *          powers of 7.
 * https://oeis.org/A297180
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = a(n-1) + 7*a(n-3) - 7*a(n-4) (n > 4)
 * Range:     u8 n <= 10, u16 n <= 19, u32 n <= 35, u64 n <= 70, u128 n <= 138,
 *            big any n
 * Helpers:   seq_realloc
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Initial values: a(1)=1, a(2)=2, a(3)=3, a(4)=4  */

#include <stdlib.h>
#include <stddef.h>
#include "../utils/seq_realloc.h"  /* provides seq_realloc */

seq_t a(idx_t n)
{
    /* n is 1‑based.  For n == 0 return 0 (unused). */
    if (n == 0)
        return (seq_t)0;

    /* static cache with memoisation */
    static seq_t *cache = NULL;   /* array index 0..cap-1  */
    static idx_t   cap   = 0;     /* number of elements allocated */

    if (n >= cap) {                       /* need to grow cache  */
        size_t newcap = (size_t)n + 1;    /* indices 0..n  */
        seq_t *newbuf = seq_realloc(cache, cap, newcap);
        if (!newbuf)                       /* allocation failure  */
            abort();

        cache = newbuf;

        /* initialise new elements */
        for (idx_t i = cap; i < newcap; ++i) {
            if (i == 0)
                continue;                 /* unused */
            if (i <= 4) {
                cache[i] = (seq_t)i;       /* a(1)..a(4) */
            } else {
                cache[i] = cache[i-1]          /* a(n-1)   */
                           + (seq_t)7 * cache[i-3]   /* 7*a(n-3) */
                           - (seq_t)7 * cache[i-4];  /* 7*a(n-4) */
            }
        }
        cap = newcap;
    }

    return cache[n];
}
